insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id":5039,"materia":"enf","nivel":0,"enunciado":"Logo após o nascimento, o contato pele a pele entre mãe e bebê saudável ajuda a:","opcoes":["Manter a temperatura do bebê e favorecer a amamentação na primeira hora","Aumentar o risco de hipotermia, atrasar o vínculo e dificultar a primeira mamada do bebê","Atrasar a amamentação","Substituir o teste do pezinho"],"explicacao":"Conhecido como 'hora de ouro'."},{"id":5040,"materia":"enf","nivel":0,"enunciado":"Ao nascer, o recém-nascido recebe vitamina K por via intramuscular para prevenir:","opcoes":["Doença hemorrágica do recém-nascido","Icterícia","Anemia ferropriva nos primeiros meses de vida","Infecção urinária"],"explicacao":"O bebê nasce com pouca vitamina K, importante para a coagulação."},{"id":5041,"materia":"enf","nivel":0,"enunciado":"No recém-nascido em fototerapia para icterícia, é obrigatório:","opcoes":["Proteger os olhos","Cobrir todo o corpo com roupa","Suspender a amamentação","Manter a luz desligada à noite toda"],"explicacao":"A luz pode lesar a retina."},{"id":5042,"materia":"enf","nivel":0,"enunciado":"O único método contraceptivo que também previne infecções sexualmente transmissíveis é o:","opcoes":["Preservativo (camisinha)","DIU de cobre","Anticoncepcional oral combinado","Laqueadura"],"explicacao":"Pode ser associado a outro método (dupla proteção)."},{"id":5043,"materia":"enf","nivel":0,"enunciado":"O DIU de cobre, oferecido no SUS, tem duração de uso de cerca de:","opcoes":["10 anos","1 mês","6 meses","1 ano"],"explicacao":"Não contém hormônio."},{"id":5044,"materia":"enf","nivel":0,"enunciado":"A insulina fechada, ainda não usada, deve ser guardada:","opcoes":["Na geladeira, entre 2 °C e 8 °C, sem congelar","No congelador","Ao sol","No porta-luvas do carro, para levar a todo lugar"],"explicacao":"Insulina congelada perde o efeito e deve ser descartada."},{"id":5045,"materia":"enf","nivel":0,"enunciado":"Na aplicação de insulina, o rodízio dos locais serve para:","opcoes":["Evitar lipodistrofia (alterações na gordura da pele)","Aumentar a dor","Acelerar a validade e aumentar o efeito de cada dose de insulina","Dispensar a higiene"],"explicacao":"Locais: abdome, coxas, braços e nádegas."},{"id":5046,"materia":"enf","nivel":0,"enunciado":"Antes de medir a pressão arterial, a pessoa deve:","opcoes":["Ficar em repouso por 3 a 5 minutos, com a bexiga vazia","Fazer exercício por 10 minutos para aquecer o corpo e o braço","Fumar um cigarro para relaxar","Tomar café"],"explicacao":"Também deve estar sentada, com as pernas descruzadas."},{"id":5047,"materia":"enf","nivel":0,"enunciado":"A frequência cardíaca normal de um recém-nascido em repouso é de cerca de:","opcoes":["120 a 160 batimentos por minuto","40 a 60 batimentos por minuto","60 a 80 batimentos por minuto","200 a 250 batimentos por minuto"],"explicacao":"Bem mais alta que a do adulto."},{"id":5048,"materia":"enf","nivel":0,"enunciado":"Diante de suspeita ou confirmação de maus-tratos contra criança, o profissional de saúde deve comunicar:","opcoes":["O Conselho Tutelar","Apenas a escola","Somente a família","Ninguém, por sigilo"],"explicacao":"Obrigação prevista no ECA (art. 13)."},{"id":5049,"materia":"enf","nivel":0,"enunciado":"Na Caderneta da Criança, a curva de crescimento serve para:","opcoes":["Acompanhar peso, comprimento e perímetro cefálico ao longo do tempo","Registrar apenas as vacinas","Marcar consultas com o dentista e o oftalmologista ao longo da infância","Controlar a mesada"],"explicacao":"Mudanças na curva podem indicar problemas de saúde."},{"id":5050,"materia":"enf","nivel":0,"enunciado":"Antes da coleta de hemocultura, deve-se, sempre que possível:","opcoes":["Coletar antes de iniciar o antibiótico","Dar o antibiótico primeiro","Usar o mesmo acesso do soro, sem antissepsia","Coletar só depois da alta"],"explicacao":"O antibiótico pode impedir o crescimento da bactéria no exame."},{"id":5051,"materia":"enf","nivel":0,"enunciado":"Pupilas com o mesmo tamanho são chamadas de:","opcoes":["Isocóricas","Anisocóricas","Midriáticas","Mióticas"],"explicacao":"Anisocoria: pupilas de tamanhos diferentes."},{"id":5052,"materia":"enf","nivel":0,"enunciado":"Em feridas, o curativo que mantém o meio úmido:","opcoes":["Favorece a cicatrização","Impede a cicatrização","Deve ser evitado sempre","Causa necrose"],"explicacao":"Ferida ressecada cicatriza mais devagar."},{"id":5053,"materia":"enf","nivel":0,"enunciado":"Para coleta de gasometria arterial na artéria radial, verifica-se antes a circulação colateral com o:","opcoes":["Teste de Allen","Teste do pezinho","Teste do laço","Teste de Romberg"],"explicacao":"Avalia o fluxo pela artéria ulnar."},{"id":5054,"materia":"enf","nivel":0,"enunciado":"A violência contra a mulher atendida em serviço de saúde:","opcoes":["É de notificação compulsória","Nunca deve ser registrada","Só é notificada se a polícia pedir","É notificada apenas em hospitais privados"],"explicacao":"Lei nº 10.778/2003."},{"id":5055,"materia":"enf","nivel":0,"enunciado":"O clampeamento oportuno (tardio) do cordão umbilical em recém-nascido saudável é feito após cerca de:","opcoes":["1 a 3 minutos","10 segundos, sempre","30 minutos","2 horas"],"explicacao":"Melhora os estoques de ferro do bebê."},{"id":5056,"materia":"enf","nivel":0,"enunciado":"A Caderneta da Pessoa Idosa é usada para:","opcoes":["Acompanhar a saúde do idoso, incluindo riscos e vulnerabilidades","Pagar passagens de ônibus","Substituir o RG","Registrar só as vacinas tomadas na infância, sem outros dados de saúde"],"explicacao":"Ajuda a equipe na atenção à pessoa idosa."},{"id":5057,"materia":"enf","nivel":0,"enunciado":"A icterícia que aparece nas primeiras 24 horas de vida é considerada:","opcoes":["Patológica, exigindo investigação","Fisiológica e sem importância, sem precisar de avaliação","Normal em todos os bebês","Sinal de bom desenvolvimento"],"explicacao":"A fisiológica costuma surgir depois de 24 horas."},{"id":5058,"materia":"enf","nivel":1,"enunciado":"Na comunicação terapêutica em saúde mental, é uma atitude adequada:","opcoes":["Escutar com atenção e acolher, sem julgar","Discutir com o paciente até convencê-lo de que está errado","Ignorar o que ele relata","Rir das ideias do paciente"],"explicacao":"A escuta qualificada fortalece o vínculo."},{"id":5059,"materia":"enf","nivel":1,"enunciado":"A contenção mecânica de um paciente agitado deve ser:","opcoes":["O último recurso, com prescrição, monitorização e registro","A primeira medida em qualquer situação de agitação, mesmo leve","Feita como forma de punição","Mantida sem tempo definido"],"explicacao":"Antes, tentam-se a abordagem verbal e outras medidas."},{"id":5060,"materia":"enf","nivel":1,"enunciado":"O curativo de alginato de cálcio é indicado principalmente para feridas:","opcoes":["Com muito exsudato","Secas e sem secreção","Já cicatrizadas","Com tecido de granulação seco"],"explicacao":"Absorve o exsudato e forma um gel."},{"id":5061,"materia":"enf","nivel":1,"enunciado":"O curativo com carvão ativado e prata é útil em feridas:","opcoes":["Com odor e infecção","Totalmente limpas e secas","Recém-suturadas","De primeiro grau"],"explicacao":"O carvão absorve odores e a prata tem ação antimicrobiana."},{"id":5062,"materia":"enf","nivel":1,"enunciado":"Os ácidos graxos essenciais (AGE) são usados principalmente para:","opcoes":["Proteger a pele íntegra e prevenir lesões","Esterilizar materiais","Tratar infecção sistêmica grave por via oral","Desobstruir sondas"],"explicacao":"Muito usados na prevenção de lesão por pressão."},{"id":5063,"materia":"enf","nivel":1,"enunciado":"No ECG, o eletrodo V1 fica no:","opcoes":["4º espaço intercostal, à direita do esterno","5º espaço intercostal, na linha axilar média esquerda","Punho direito","Abdome"],"explicacao":"V2 fica no 4º espaço à esquerda do esterno."},{"id":5064,"materia":"enf","nivel":1,"enunciado":"A suspeita de violência contra a pessoa idosa, pelo Estatuto da Pessoa Idosa, deve ser:","opcoes":["Notificada obrigatoriamente pelos serviços de saúde","Mantida em segredo","Resolvida só pela família, sem interferência da equipe","Ignorada se o idoso negar"],"explicacao":"Os casos são comunicados aos órgãos previstos em lei."},{"id":5065,"materia":"enf","nivel":1,"enunciado":"No climatério, um sintoma frequente é:","opcoes":["Ondas de calor (fogachos)","Aumento da menstruação para sempre","Crescimento da altura","Melhora da visão"],"explicacao":"Relacionado à queda dos hormônios ovarianos."},{"id":5066,"materia":"enf","nivel":1,"enunciado":"Depois de aberto e em uso, o frasco de insulina pode ficar em temperatura ambiente fresca por cerca de:","opcoes":["4 semanas, conforme o fabricante","1 ano","1 dia","10 minutos fora da geladeira, no máximo"],"explicacao":"Longe do calor e da luz direta."},{"id":5067,"materia":"enf","nivel":1,"enunciado":"No idoso, o uso de muitos medicamentos ao mesmo tempo (polifarmácia) aumenta o risco de:","opcoes":["Interações, efeitos adversos e quedas","Ganho de força muscular","Melhora automática de todas as doenças","Aumento da visão"],"explicacao":"Revisar periodicamente a lista de remédios é essencial."},{"id":5068,"materia":"enf","nivel":1,"enunciado":"Pela Lei nº 7.498/1986, o enfermeiro pode realizar:","opcoes":["Parto sem distocia (normal, sem complicação)","Cirurgia cesariana","Prescrição de qualquer medicamento, sem protocolo","Anestesia geral"],"explicacao":"Também assistência à parturiente e identificação de distocias."},{"id":5069,"materia":"enf","nivel":1,"enunciado":"O PICC (cateter central de inserção periférica) pode ser inserido por:","opcoes":["Enfermeiro habilitado","Técnico de enfermagem","Auxiliar de enfermagem","Qualquer profissional sem treinamento"],"explicacao":"Exige capacitação específica, conforme o Cofen."},{"id":5070,"materia":"enf","nivel":1,"enunciado":"No recém-nascido, a profilaxia ocular é feita para prevenir:","opcoes":["Conjuntivite neonatal, como a gonocócica","Catarata congênita, glaucoma e miopia","Miopia","Estrabismo"],"explicacao":"Feita logo após o nascimento."},{"id":5071,"materia":"enf","nivel":1,"enunciado":"Anisocoria súbita em paciente com trauma de crânio sugere:","opcoes":["Possível lesão cerebral grave, exigindo avaliação urgente","Cansaço visual","Situação normal, sem necessidade de comunicar nem reavaliar o paciente","Alergia"],"explicacao":"Deve ser comunicada imediatamente."},{"id":5072,"materia":"enf","nivel":2,"enunciado":"O hidrocoloide é indicado principalmente para feridas:","opcoes":["Limpas, com pouco a moderado exsudato","Infectadas, com muito pus e tecido necrótico","Com exposição de osso","Com sangramento ativo"],"explicacao":"Mantém o meio úmido e pode ficar alguns dias."},{"id":5073,"materia":"enf","nivel":2,"enunciado":"Em pessoa com risco de suicídio, a conduta da equipe inclui:","opcoes":["Perguntar diretamente sobre a ideação, acolher e garantir acompanhamento","Evitar falar do assunto para não 'dar ideias', mudar logo de conversa e deixar para outro dia","Deixar a pessoa sozinha para refletir","Encaminhar sem conversar"],"explicacao":"Perguntar não aumenta o risco; ajuda a avaliar e proteger."},{"id":5074,"materia":"enf","nivel":2,"enunciado":"No uso de lítio, a equipe deve observar sinais de intoxicação, como:","opcoes":["Tremor grosseiro, vômitos, diarreia e confusão","Ganho de força","Aumento do apetite apenas, sem outros sinais ou sintomas","Melhora do sono"],"explicacao":"O nível no sangue é monitorado periodicamente."},{"id":5075,"materia":"enf","nivel":2,"enunciado":"Em idoso com confusão mental de início súbito, deve-se suspeitar de:","opcoes":["Delirium, muitas vezes causado por infecção, desidratação ou medicamentos","Envelhecimento normal","Preguiça","Demência, sempre, sem necessidade de investigar infecções, remédios ou outras causas"],"explicacao":"É uma urgência clínica."},{"id":5076,"materia":"enf","nivel":2,"enunciado":"Na amamentação, a pega correta inclui:","opcoes":["Boca bem aberta, lábio inferior virado para fora e mais aréola visível acima da boca","Bebê sugando só o bico","Bochechas encovadas","Barulho de estalos a cada sucção, bochechas encovadas e o bebê pegando só o bico"],"explicacao":"A pega errada causa fissuras e pouca transferência de leite."},{"id":5077,"materia":"enf","nivel":2,"enunciado":"Em paciente com traqueostomia, a aspiração deve ser feita com técnica:","opcoes":["Estéril","Limpa, sem luvas","Sem higiene das mãos","Com a mesma sonda reutilizada o dia todo"],"explicacao":"Reduz o risco de pneumonia."},{"id":5078,"materia":"enf","nivel":2,"enunciado":"Na lavagem gástrica (quando indicada) e na sondagem nasogástrica, o paciente consciente deve ficar, de preferência:","opcoes":["Em posição de Fowler, com a cabeça elevada","Em Trendelenburg","Deitado de bruços, com a cabeça virada para o lado","Em pé"],"explicacao":"Reduz o risco de aspiração."},{"id":5079,"materia":"enf","nivel":2,"enunciado":"O exame de prevenção do câncer de mama recomendado pelo Ministério da Saúde para rastreamento é a:","opcoes":["Mamografia","Ultrassom de abdome","Tomografia de crânio","Radiografia de tórax"],"explicacao":"A faixa etária e a periodicidade seguem as diretrizes vigentes do Ministério da Saúde."},{"id":5080,"materia":"enf","nivel":3,"enunciado":"Uma criança de 2 anos com febre de 39 °C. A dipirona prescrita é de 15 mg/kg e a criança pesa 12 kg. A solução tem 500 mg/mL (20 gotas/mL). A dose em gotas é de:","opcoes":["Cerca de 7 gotas","20 gotas, uma por quilo","36 gotas","2 gotas"],"explicacao":"12 × 15 = 180 mg = 0,36 mL × 20 ≈ 7 gotas."},{"id":5081,"materia":"enf","nivel":3,"enunciado":"Em paciente com edema agudo de pulmão, a posição recomendada é:","opcoes":["Sentado, com as pernas pendentes","Deitado reto, com as pernas elevadas","Em Trendelenburg","De bruços"],"explicacao":"Diminui o retorno venoso e melhora a respiração."},{"id":5082,"materia":"enf","nivel":3,"enunciado":"A taxa de infusão de 2 mL/h de um medicamento com concentração de 4 mg/mL corresponde a:","opcoes":["8 mg/h","2 mg/h","0,5 mg/h","16 mg/h"],"explicacao":"2 mL/h × 4 mg/mL."},{"id":5083,"materia":"enf","nivel":3,"enunciado":"No aleitamento, a mãe que vive com HIV, segundo as recomendações do SUS:","opcoes":["Não deve amamentar, e o bebê recebe fórmula infantil","Deve amamentar normalmente","Deve amamentar só à noite","Pode amamentar se não tiver febre nem feridas no seio"],"explicacao":"O SUS fornece a fórmula láctea."},{"id":5084,"materia":"enf","nivel":4,"enunciado":"Um soro de 500 mL com 10 UI de ocitocina corre a 30 mL/h. A dose por hora é de:","opcoes":["0,6 UI/h","6 UI/h","0,06 UI/h","3 UI/h"],"explicacao":"10 UI ÷ 500 mL = 0,02 UI/mL; × 30 = 0,6 UI/h."},{"id":5085,"materia":"enf","nivel":4,"enunciado":"Pela classificação do recém-nascido, um bebê nascido com 36 semanas é:","opcoes":["Pré-termo","A termo","Pós-termo","Prematuro extremo"],"explicacao":"A termo: de 37 a 41 semanas e 6 dias."},{"id":5086,"materia":"enf","nivel":4,"enunciado":"Um recém-nascido com peso de nascimento inferior a 2.500 g é classificado como:","opcoes":["Baixo peso ao nascer","Peso adequado","Macrossômico","Grande para a idade gestacional"],"explicacao":"Abaixo de 1.500 g: muito baixo peso."},{"id":5087,"materia":"enf","nivel":4,"enunciado":"A escala de Glasgow com resposta pupilar (Glasgow-P) subtrai pontos quando:","opcoes":["Uma ou as duas pupilas não reagem à luz","O paciente abre os olhos espontaneamente","A fala é orientada","O paciente obedece comandos"],"explicacao":"A nova versão integra a reatividade pupilar ao escore."},{"id":5088,"materia":"sus","nivel":0,"enunciado":"Os Conselhos de Saúde são compostos por representantes:","opcoes":["Do governo, dos prestadores de serviço, dos profissionais de saúde e dos usuários","Apenas dos médicos","Somente dos políticos eleitos, de seus assessores e de empresários ligados à saúde","Das empresas farmacêuticas"],"explicacao":"Os usuários ocupam metade das vagas."},{"id":5089,"materia":"sus","nivel":0,"enunciado":"O Plano de Saúde, instrumento de planejamento do SUS, tem vigência de:","opcoes":["Quatro anos","Um mês","Dez anos, sem revisões","Um dia"],"explicacao":"É detalhado na Programação Anual de Saúde."},{"id":5090,"materia":"sus","nivel":0,"enunciado":"O CNES é o cadastro nacional de:","opcoes":["Estabelecimentos de saúde","Pacientes com câncer em tratamento","Escolas","Empresas de ônibus"],"explicacao":"Reúne dados de unidades, equipes e profissionais."},{"id":5091,"materia":"sus","nivel":0,"enunciado":"Na Estratégia Saúde da Família, a área de atuação de cada ACS é chamada de:","opcoes":["Microárea","Macrorregião","Capital","Distrito federal"],"explicacao":"Várias microáreas formam a área da equipe."},{"id":5092,"materia":"sus","nivel":0,"enunciado":"O VIGIAGUA é o programa de vigilância da:","opcoes":["Qualidade da água para consumo humano","Água das piscinas de clubes e academias","Chuva ácida","Água dos oceanos"],"explicacao":"Parte da vigilância em saúde ambiental."},{"id":5093,"materia":"sus","nivel":0,"enunciado":"O Relatório Anual de Gestão (RAG) serve para:","opcoes":["Apresentar os resultados alcançados com a Programação Anual de Saúde","Contratar médicos","Vender serviços","Registrar nascimentos, casamentos e óbitos nos cartórios do município"],"explicacao":"É analisado pelo Conselho de Saúde."},{"id":5094,"materia":"sus","nivel":0,"enunciado":"O SIOPS é o sistema que acompanha:","opcoes":["Os orçamentos públicos em saúde","As vacinas aplicadas nas unidades","Os nascidos vivos","As internações"],"explicacao":"Mostra quanto cada ente aplica em saúde."},{"id":5095,"materia":"sus","nivel":1,"enunciado":"Pela Lei nº 8.142/1990, a Conferência de Saúde é convocada:","opcoes":["Pelo Poder Executivo ou, extraordinariamente, por ela própria ou pelo Conselho de Saúde","Apenas pelo Poder Judiciário, a pedido do Ministério Público, a cada dez anos","Somente pelos hospitais","Pelos partidos políticos"],"explicacao":"Avalia a situação de saúde e propõe diretrizes."},{"id":5096,"materia":"sus","nivel":1,"enunciado":"A Resolução CNS nº 453/2012 trata:","opcoes":["Das diretrizes para instituição, reformulação e funcionamento dos Conselhos de Saúde","Do Código de Ética dos Profissionais de Enfermagem e das penalidades aplicadas pelo Cofen","Do calendário vacinal","Da segurança do paciente"],"explicacao":"Detalha composição e funcionamento dos conselhos."},{"id":5097,"materia":"sus","nivel":1,"enunciado":"A Política Nacional de Plantas Medicinais e Fitoterápicos busca:","opcoes":["Garantir acesso seguro e uso racional de plantas medicinais e fitoterápicos","Proibir o uso de chás","Substituir todos os medicamentos","Vender plantas e chás nas farmácias privadas, sem nenhum controle de qualidade nem orientação"],"explicacao":"Instituída em 2006."},{"id":5098,"materia":"sus","nivel":1,"enunciado":"O SI-PNI registra:","opcoes":["As vacinas aplicadas na população","As internações hospitalares e os procedimentos cirúrgicos","Os gastos com saúde","Os profissionais de saúde"],"explicacao":"Permite acompanhar a cobertura vacinal."},{"id":5099,"materia":"sus","nivel":1,"enunciado":"A territorialização na atenção primária serve para:","opcoes":["Conhecer a população, os riscos e os recursos da área de abrangência da equipe","Mudar o nome dos bairros","Definir impostos municipais, taxas de lixo e o valor do IPTU de cada bairro da cidade","Escolher o prefeito"],"explicacao":"Base para o planejamento local."},{"id":5100,"materia":"sus","nivel":2,"enunciado":"A Programação Anual de Saúde (PAS):","opcoes":["Operacionaliza as intenções do Plano de Saúde a cada ano","Substitui o Plano de Saúde e dispensa o Relatório de Gestão","É feita a cada dez anos","É um documento privado"],"explicacao":"Seus resultados aparecem no Relatório Anual de Gestão."},{"id":5101,"materia":"sus","nivel":2,"enunciado":"O e-SUS APS é a estratégia para:","opcoes":["Informatizar e qualificar os registros da atenção primária","Vender medicamentos online","Marcar viagens","Substituir o prontuário eletrônico por fichas de papel guardadas em arquivo"],"explicacao":"Inclui o prontuário eletrônico do cidadão (PEC)."},{"id":5102,"materia":"sus","nivel":2,"enunciado":"A vigilância em saúde do trabalhador atua para:","opcoes":["Identificar e intervir nos riscos à saúde nos ambientes e processos de trabalho","Fiscalizar impostos das empresas e aplicar multas tributárias aos empregadores","Contratar trabalhadores","Definir salários"],"explicacao":"Integra a vigilância em saúde do SUS."},{"id":5103,"materia":"sus","nivel":3,"enunciado":"As zoonoses são:","opcoes":["Doenças transmitidas entre animais e seres humanos","Doenças exclusivas de plantas e lavouras do campo","Doenças genéticas","Doenças causadas pelo frio"],"explicacao":"Ex.: raiva, leptospirose e leishmaniose."},{"id":5104,"materia":"sus","nivel":3,"enunciado":"A PNAB 2017 passou a prever, além da equipe de Saúde da Família, a:","opcoes":["Equipe de Atenção Básica (eAB), depois chamada de equipe de Atenção Primária (eAP)","Equipe de cirurgia cardíaca de alta complexidade em hospital de referência estadual","Equipe de transporte aéreo","Equipe de segurança armada"],"explicacao":"Com composição e carga horária próprias."},{"id":5105,"materia":"sus","nivel":3,"enunciado":"A carga horária dos profissionais da equipe de Saúde da Família, segundo a PNAB, é em geral de:","opcoes":["40 horas semanais","10 horas semanais","80 horas semanais","4 horas semanais"],"explicacao":"Com exceções previstas para alguns profissionais."},{"id":5106,"materia":"sus","nivel":4,"enunciado":"Pela Lei nº 8.080/1990, a assistência terapêutica integral inclui a:","opcoes":["Dispensação de medicamentos conforme protocolos clínicos e diretrizes terapêuticas","Distribuição de qualquer produto sem critério nem registro sanitário, a pedido do usuário","Venda de medicamentos importados sem registro","Entrega apenas de vitaminas"],"explicacao":"Incluído pela Lei nº 12.401/2011."},{"id":5107,"materia":"sus","nivel":4,"enunciado":"A incorporação de novas tecnologias e medicamentos ao SUS é avaliada pela:","opcoes":["Conitec (Comissão Nacional de Incorporação de Tecnologias no SUS)","Polícia Federal","Receita Federal","Câmara dos Vereadores de cada município, por votação aberta"],"explicacao":"Considera evidências de eficácia, segurança e custo."},{"id":5108,"materia":"med","nivel":0,"enunciado":"Na depressão, a classe de antidepressivos geralmente usada como primeira escolha é a dos:","opcoes":["Inibidores seletivos da recaptação de serotonina, como fluoxetina e sertralina","Antibióticos","Anticoagulantes orais, como a varfarina, usados em doses altas","Diuréticos"],"explicacao":"O efeito pleno costuma levar algumas semanas."},{"id":5109,"materia":"med","nivel":0,"enunciado":"No diabetes tipo 2, o medicamento oral geralmente de primeira escolha é a:","opcoes":["Metformina","Insulina regular","Dipirona","Omeprazol"],"explicacao":"Associada a mudanças no estilo de vida."},{"id":5110,"materia":"med","nivel":0,"enunciado":"A levotiroxina, no hipotireoidismo, deve ser tomada:","opcoes":["Em jejum, cerca de 30 minutos antes do café","Junto com o almoço","Só quando houver sintomas","À noite, após o jantar, com um copo de leite"],"explicacao":"Alimentos e cálcio atrapalham a absorção."},{"id":5111,"materia":"med","nivel":0,"enunciado":"O uso prolongado de benzodiazepínicos, como diazepam e clonazepam, tem risco de:","opcoes":["Dependência e quedas, principalmente em idosos","Aumento da força muscular e da atenção nas tarefas","Cura da depressão","Melhora da memória"],"explicacao":"Devem ser usados pelo menor tempo possível."},{"id":5112,"materia":"med","nivel":0,"enunciado":"Na gestação, a bacteriúria assintomática deve ser:","opcoes":["Tratada, pelo risco de infecção urinária grave e parto prematuro","Ignorada sempre","Tratada só depois do parto, para não afetar o bebê durante a gestação","Tratada apenas com chá"],"explicacao":"Por isso se faz urocultura no pré-natal."},{"id":5113,"materia":"med","nivel":0,"enunciado":"Um anti-hipertensivo considerado seguro e muito usado na gestação é a:","opcoes":["Metildopa","Losartana","Enalapril","Captopril"],"explicacao":"IECA e BRA são contraindicados na gestação."},{"id":5114,"materia":"med","nivel":1,"enunciado":"O Ministério da Saúde e o INCA não recomendam o rastreamento populacional do câncer de próstata em homens sem sintomas porque:","opcoes":["Os possíveis danos do rastreamento superam os benefícios","O exame é proibido","O câncer de próstata é raro no Brasil e quase não causa mortes","É sempre fatal"],"explicacao":"A decisão deve ser compartilhada quando o homem solicitar."},{"id":5115,"materia":"med","nivel":1,"enunciado":"A metformina deve ser evitada quando a taxa de filtração glomerular estiver abaixo de:","opcoes":["30 mL/min","90 mL/min","120 mL/min","150 mL/min"],"explicacao":"Pelo risco de acidose lática."},{"id":5116,"materia":"med","nivel":1,"enunciado":"Na ansiedade generalizada, um tratamento de primeira linha inclui:","opcoes":["Psicoterapia e, quando indicado, ISRS","Benzodiazepínico diário por anos, como única medida","Antibiótico","Cirurgia"],"explicacao":"Benzodiazepínicos são para uso pontual e curto."},{"id":5117,"materia":"med","nivel":1,"enunciado":"Em idosos, uma causa comum de delirium é:","opcoes":["Infecção, como a urinária ou a pneumonia","Excesso de exercício","Leitura","Alimentação equilibrada e sono regular"],"explicacao":"Também desidratação e medicamentos."},{"id":5118,"materia":"med","nivel":1,"enunciado":"A vacina contra o pneumococo e a contra a influenza são especialmente recomendadas para:","opcoes":["Idosos e pessoas com doenças crônicas","Somente crianças saudáveis em idade escolar","Apenas atletas","Ninguém"],"explicacao":"Reduzem internações e mortes."},{"id":5119,"materia":"med","nivel":2,"enunciado":"Na insuficiência cardíaca com fração de ejeção reduzida, medicamentos que reduzem a mortalidade incluem:","opcoes":["IECA ou BRA, betabloqueadores e espironolactona","Apenas diuréticos de alça em doses altas, sem outros remédios","Antibióticos","Anti-inflamatórios"],"explicacao":"Diuréticos aliviam a congestão, mas não reduzem a mortalidade."},{"id":5120,"materia":"med","nivel":2,"enunciado":"Anti-inflamatórios não esteroides devem ser evitados em pacientes com:","opcoes":["Insuficiência renal, insuficiência cardíaca e úlcera péptica","Dor leve de cabeça ocasional, sem outras doenças nem uso de remédios","Gripe sem complicações","Pele saudável"],"explicacao":"Podem piorar a função renal e causar sangramento."},{"id":5121,"materia":"med","nivel":3,"enunciado":"No hipotireoidismo subclínico, o TSH está:","opcoes":["Elevado, com T4 livre normal","Baixo, com T4 alto","Normal, com T4 livre baixo e sintomas intensos","Ausente"],"explicacao":"Nem sempre precisa de tratamento."},{"id":5122,"materia":"med","nivel":4,"enunciado":"Um paciente usa varfarina. O exame usado para controlar a dose é o:","opcoes":["INR (tempo de protrombina)","Hemoglobina glicada (HbA1c)","TSH","Ácido úrico"],"explicacao":"Muitos alimentos e medicamentos interferem na varfarina."},{"id":5123,"materia":"fisio","nivel":0,"enunciado":"A escala do MRC gradua a força muscular de:","opcoes":["0 (nenhuma contração) a 5 (força normal)","1 a 100, em porcentagem do peso","A a Z","0 a 3"],"explicacao":"Grau 3: vence a gravidade, sem resistência."},{"id":5124,"materia":"fisio","nivel":0,"enunciado":"A goniometria mede:","opcoes":["A amplitude de movimento das articulações","A pressão arterial","A força de preensão","A capacidade pulmonar em litros"],"explicacao":"Feita com o goniômetro."},{"id":5125,"materia":"fisio","nivel":0,"enunciado":"O teste de Romberg avalia:","opcoes":["O equilíbrio, com os pés juntos e os olhos fechados","A força das mãos","A visão","O reflexo do joelho (patelar) e do tornozelo"],"explicacao":"Positivo sugere problema de propriocepção."},{"id":5126,"materia":"fisio","nivel":0,"enunciado":"A órtese tornozelo-pé (AFO) é indicada, por exemplo, para:","opcoes":["Pé caído","Fratura de clavícula","Dor de cabeça","Lesão no punho"],"explicacao":"Mantém o pé em posição durante a marcha."},{"id":5127,"materia":"fisio","nivel":0,"enunciado":"O índice de Barthel avalia:","opcoes":["A independência nas atividades de vida diária","A força dos músculos respiratórios em repouso","A dor","A visão"],"explicacao":"Ex.: alimentar-se, tomar banho, vestir-se."},{"id":5128,"materia":"fisio","nivel":1,"enunciado":"A marcha atáxica, com base alargada e instável, é típica de lesão:","opcoes":["Cerebelar","Do joelho","Do ombro","Da mão"],"explicacao":"Associada à falta de coordenação."},{"id":5129,"materia":"fisio","nivel":1,"enunciado":"O teste Timed Up and Go (TUG) avalia:","opcoes":["Mobilidade e risco de quedas","Força de preensão","Capacidade pulmonar total","Amplitude do ombro"],"explicacao":"Levantar, andar 3 metros, voltar e sentar."},{"id":5130,"materia":"fisio","nivel":1,"enunciado":"A CPAP é útil no edema agudo de pulmão cardiogênico porque:","opcoes":["Melhora a oxigenação e reduz o trabalho respiratório","Aumenta o retorno venoso e a congestão pulmonar do paciente","Diminui a oxigenação","Substitui o diurético"],"explicacao":"É uma forma de ventilação não invasiva."},{"id":5131,"materia":"fisio","nivel":1,"enunciado":"A Medida de Independência Funcional (MIF) avalia:","opcoes":["O grau de ajuda que a pessoa precisa para atividades motoras e cognitivas","Apenas a força do quadríceps, sem considerar aspectos cognitivos ou de comunicação","A pressão arterial","A visão de cores"],"explicacao":"Muito usada em reabilitação."},{"id":5132,"materia":"fisio","nivel":2,"enunciado":"Em doenças neuromusculares com tosse fraca, a fisioterapia usa:","opcoes":["Técnicas de tosse assistida","Repouso total sem exercícios respiratórios","Apenas medicamentos","Gesso no tórax"],"explicacao":"Ajudam a eliminar secreções e prevenir infecções."},{"id":5133,"materia":"fisio","nivel":2,"enunciado":"O conceito Bobath é usado principalmente na reabilitação de:","opcoes":["Pessoas com lesões neurológicas, como AVC e paralisia cerebral","Fraturas de dedo","Entorses leves","Queimaduras de primeiro grau e entorses leves de tornozelo"],"explicacao":"Trabalha o controle motor e a função."},{"id":5134,"materia":"fisio","nivel":2,"enunciado":"A Facilitação Neuromuscular Proprioceptiva (Kabat) usa:","opcoes":["Padrões diagonais de movimento","Apenas eletroterapia","Somente gelo","Movimentos só em um plano reto"],"explicacao":"Estimula força, coordenação e amplitude."},{"id":5135,"materia":"fisio","nivel":3,"enunciado":"Na prótese para amputação transtibial, o apoio de peso ocorre principalmente:","opcoes":["No tendão patelar e em áreas tolerantes do coto","Na ponta do osso cortado","No pé contralateral apenas, sem nenhum contato do coto com o encaixe","No quadril"],"explicacao":"O encaixe deve ser bem ajustado."},{"id":5136,"materia":"fisio","nivel":3,"enunciado":"Na dor neuropática, a pessoa costuma relatar:","opcoes":["Queimação, choques e formigamento","Dor só ao apertar o músculo, sem formigamento","Rigidez matinal curta","Dor apenas ao correr"],"explicacao":"Ex.: após AVC, lesão medular ou diabetes."},{"id":5137,"materia":"fisio","nivel":4,"enunciado":"Na reabilitação cardíaca, a fase II corresponde, em geral, ao período:","opcoes":["Ambulatorial supervisionado após a alta hospitalar","De internação na UTI","De manutenção por toda a vida, sem nenhuma supervisão profissional","Anterior ao diagnóstico"],"explicacao":"A fase I é hospitalar; a III e a IV são de manutenção."},{"id":5138,"materia":"enf","nivel":2,"enunciado":"Dor na panturrilha à dorsiflexão do pé (sinal de Homans), com inchaço e calor em uma perna, sugere:","opcoes":["Trombose venosa profunda","Câimbra comum","Entorse de tornozelo com lesão de ligamento","Unha encravada"],"explicacao":"O sinal é pouco sensível; a confirmação é feita por ultrassom com Doppler."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('sus','enf','fisio','med') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
